def rgb(h):return tuple(int(h[i:i+2],16) for i in (0,2,4))
def cmyk(h):
    r,g,b=[x/255 for x in rgb(h)];k=1-max(r,g,b)
    if k==1:return (0,0,0,100)
    return tuple(round(x*100) for x in ((1-r-k)/(1-k),(1-g-k)/(1-k),(1-b-k)/(1-k),k))
def lum(h):
    def c(v):v/=255;return v/12.92 if v<=.03928 else ((v+.055)/1.055)**2.4
    r,g,b=rgb(h);return .2126*c(r)+.7152*c(g)+.0722*c(b)
def cr(a,b):x,y=sorted([lum(a),lum(b)],reverse=True);return (x+.05)/(y+.05)
P=[]
def page(cls,title,body,num=True):P.append((cls,title,body,num))
def head(no,h,em,p=''):return f'<div class="hd"><span class="no">{no}</span><h2>{h}<br><em>{em}</em></h2>{f"<p>{p}</p>" if p else ""}</div>'
